package com.prosolution.core.domain.repository
import com.prosolution.common.NetworkResult import com.prosolution.core.domain.model.Match import com.prosolution.core.domain.model.Standing import kotlinx.coroutines.flow.Flow
interface WorldCupRepository { fun observeLiveMatches(): Flow<List<Match>> suspend fun refreshMatches(): NetworkResult<Unit> suspend fun getSchedule(day: String?): NetworkResult<List<Match>> suspend fun getStandings(group: String?): NetworkResult<List<Standing>> }

package com.prosolution.database

import androidx.room.Entity
import androidx.room.PrimaryKey

@Entity(tableName = "favorite_teams")
data class FavoriteTeamEntity(
    @PrimaryKey val teamId: String,
    val name: String,
    val crestUrl: String
)

@Entity(tableName = "schedule_cache")
data class ScheduleEntity(
    @PrimaryKey val matchId: String,
    val payload: String,
    val fetchedAt: Long
)

@Entity(tableName = "standings_cache")
data class StandingEntity(
    @PrimaryKey val id: String,
    val payload: String,
    val fetchedAt: Long
)

@Entity(tableName = "predictions")
data class PredictionEntity(
    @PrimaryKey val id: String,
    val matchId: String,
    val homeScore: Int,
    val awayScore: Int,
    val pointsEarned: Int
)

package com.prosolution.database

import androidx.room.Database
import androidx.room.RoomDatabase

@Database(
    entities = [
        FavoriteTeamEntity::class,
        ScheduleEntity::class,
        StandingEntity::class,
        PredictionEntity::class
    ],
    version = 1,
    exportSchema = false
)
abstract class GoalPulseDatabase : RoomDatabase() {
    abstract fun worldCupDao(): WorldCupDao
}

package com.prosolution.database

import androidx.room.Dao
import androidx.room.Insert
import androidx.room.OnConflictStrategy
import androidx.room.Query
import kotlinx.coroutines.flow.Flow

@Dao
interface WorldCupDao {
    @Query("SELECT * FROM schedule_cache ORDER BY fetchedAt DESC")
    fun observeSchedule(): Flow<List<ScheduleEntity>>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun upsertSchedule(items: List<ScheduleEntity>)

    @Query("DELETE FROM schedule_cache")
    suspend fun clearSchedule()

    @Query("SELECT * FROM standings_cache ORDER BY fetchedAt DESC")
    fun observeStandings(): Flow<List<StandingEntity>>

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun upsertStandings(items: List<StandingEntity>)

    @Insert(onConflict = OnConflictStrategy.REPLACE)
    suspend fun upsertPrediction(prediction: PredictionEntity)

    @Query("SELECT * FROM predictions ORDER BY pointsEarned DESC")
    fun observeLeaderboard(): Flow<List<PredictionEntity>>
}

